Short answer / bug summary
- What goes wrong: The builder used to put NULL (Python None) directly into IN/NOT IN lists as placeholders. But SQL semantics treat NULL specially: "col IN (1, NULL)" does NOT match rows where col IS NULL. So queries that expect NULL rows to be matched fail. The same applies to NOT IN: "col NOT IN (1, NULL)" will not match rows where col IS NULL, which typically isn't what callers expect.
- Effect with nested OR: When an IN that contains NULL is combined with other expressions using OR, the absence of an explicit "col IS NULL" (or "col IS NOT NULL" for NOT IN) makes the logic wrong; e.g. OR groups won't include NULL-valued rows that the caller probably intended to include.

What I changed
- The builder now:
  - Splits IN/NOT IN values into non-null values and presence of NULLs.
  - For IN:
    - If there are non-null values and NULLs: (col IN (non-null...) OR col IS NULL)
    - If only NULLs: col IS NULL
    - If only non-nulls: col IN (non-null...)
    - If empty list: (0=1) (safe, always-false)
  - For NOT IN:
    - If non-nulls and NULLs: (col NOT IN (non-null...) AND col IS NOT NULL)
    - If only NULLs: col IS NOT NULL
    - If only non-nulls: col NOT IN (non-null...)
    - If empty list: (1=1) (safe, always-true)
  - Only non-null values are placed as SQL parameters.
  - Combined forms are parenthesized to preserve correct precedence inside OR/AND groups.

Below is the complete fixed code with a test function that demonstrates the bug case (this test would have failed on the original implementation but passes with the fix):

```python
"""SQL query builder with support for complex WHERE clauses (fixed NULL handling in IN/NOT IN)."""
from typing import Any, List, Optional, Union, Tuple
from enum import Enum
from dataclasses import dataclass, field

class Op(Enum):
    EQ = "="
    NE = "!="
    LT = "<"
    GT = ">"
    LTE = "<="
    GTE = ">="
    LIKE = "LIKE"
    IN = "IN"
    NOT_IN = "NOT IN"
    IS_NULL = "IS NULL"
    IS_NOT_NULL = "IS NOT NULL"
    BETWEEN = "BETWEEN"

@dataclass
class Condition:
    column: str
    op: Op
    value: Any = None

@dataclass
class ConditionGroup:
    conditions: List[Union['Condition', 'ConditionGroup']]
    logic: str = "AND"  # AND or OR

@dataclass
class OrderBy:
    column: str
    direction: str = "ASC"

@dataclass
class JoinClause:
    table: str
    on: str
    join_type: str = "INNER"

class QueryBuilder:
    def __init__(self, table: str):
        self.table = table
        self._select: List[str] = ["*"]
        self._where: Optional[ConditionGroup] = None
        self._order_by: List[OrderBy] = []
        self._limit: Optional[int] = None
        self._offset: Optional[int] = None
        self._joins: List[JoinClause] = []
        self._group_by: List[str] = []
        self._having: Optional[ConditionGroup] = None
        self._params: List[Any] = []

    def select(self, *columns: str) -> 'QueryBuilder':
        self._select = list(columns)
        return self

    def where(self, *conditions: Union[Condition, ConditionGroup]) -> 'QueryBuilder':
        if len(conditions) == 1 and isinstance(conditions[0], ConditionGroup):
            self._where = conditions[0]
        else:
            self._where = ConditionGroup(conditions=list(conditions), logic="AND")
        return self

    def order_by(self, column: str, direction: str = "ASC") -> 'QueryBuilder':
        self._order_by.append(OrderBy(column=column, direction=direction))
        return self

    def limit(self, n: int) -> 'QueryBuilder':
        self._limit = n
        return self

    def offset(self, n: int) -> 'QueryBuilder':
        self._offset = n
        return self

    def join(self, table: str, on: str, join_type: str = "INNER") -> 'QueryBuilder':
        self._joins.append(JoinClause(table=table, on=on, join_type=join_type))
        return self

    def group_by(self, *columns: str) -> 'QueryBuilder':
        self._group_by = list(columns)
        return self

    def having(self, *conditions: Union[Condition, ConditionGroup]) -> 'QueryBuilder':
        if len(conditions) == 1 and isinstance(conditions[0], ConditionGroup):
            self._having = conditions[0]
        else:
            self._having = ConditionGroup(conditions=list(conditions), logic="AND")
        return self

    def build(self) -> Tuple[str, List[Any]]:
        self._params = []
        parts = [f"SELECT {', '.join(self._select)}"]
        parts.append(f"FROM {self.table}")

        for j in self._joins:
            parts.append(f"{j.join_type} JOIN {j.table} ON {j.on}")

        if self._where:
            where_sql = self._build_condition_group(self._where)
            parts.append(f"WHERE {where_sql}")

        if self._group_by:
            parts.append(f"GROUP BY {', '.join(self._group_by)}")

        if self._having:
            having_sql = self._build_condition_group(self._having)
            parts.append(f"HAVING {having_sql}")

        if self._order_by:
            order_parts = [f"{o.column} {o.direction}" for o in self._order_by]
            parts.append(f"ORDER BY {', '.join(order_parts)}")

        if self._limit is not None:
            parts.append(f"LIMIT {self._limit}")

        if self._offset is not None:
            parts.append(f"OFFSET {self._offset}")

        return " ".join(parts), self._params

    def _build_condition_group(self, group: ConditionGroup) -> str:
        parts = []
        for cond in group.conditions:
            if isinstance(cond, ConditionGroup):
                sub = self._build_condition_group(cond)
                parts.append(f"({sub})")
            elif isinstance(cond, Condition):
                parts.append(self._build_condition(cond))
        return f" {group.logic} ".join(parts)

    def _build_condition(self, cond: Condition) -> str:
        if cond.op == Op.IS_NULL:
            return f"{cond.column} IS NULL"
        if cond.op == Op.IS_NOT_NULL:
            return f"{cond.column} IS NOT NULL"
        if cond.op == Op.BETWEEN:
            self._params.extend(cond.value)
            return f"{cond.column} BETWEEN ? AND ?"
        if cond.op in (Op.IN, Op.NOT_IN):
            # Normalize values into a list
            values = cond.value if isinstance(cond.value, (list, tuple)) else [cond.value]
            vals_list = list(values)

            # Separate non-null values and detect presence of NULLs
            non_null_values = [v for v in vals_list if v is not None]
            has_null = any(v is None for v in vals_list)

            if cond.op == Op.IN:
                # Cases:
                # - non-nulls and nulls -> (col IN (...) OR col IS NULL)
                # - only non-nulls -> col IN (...)
                # - only nulls -> col IS NULL
                # - empty list -> always-false (0=1)
                if non_null_values:
                    placeholders = ", ".join(["?" for _ in non_null_values])
                    self._params.extend(non_null_values)
                    in_part = f"{cond.column} IN ({placeholders})"
                    if has_null:
                        return f"({in_part} OR {cond.column} IS NULL)"
                    else:
                        return in_part
                else:
                    if has_null:
                        return f"{cond.column} IS NULL"
                    else:
                        # IN with empty list -> always false
                        return "(0=1)"
            else:  # Op.NOT_IN
                # Cases:
                # - non-nulls and nulls -> (col NOT IN (...) AND col IS NOT NULL)
                # - only non-nulls -> col NOT IN (...)
                # - only nulls -> col IS NOT NULL
                # - empty list -> always-true (1=1)
                if non_null_values:
                    placeholders = ", ".join(["?" for _ in non_null_values])
                    self._params.extend(non_null_values)
                    not_in_part = f"{cond.column} NOT IN ({placeholders})"
                    if has_null:
                        return f"({not_in_part} AND {cond.column} IS NOT NULL)"
                    else:
                        return not_in_part
                else:
                    if has_null:
                        return f"{cond.column} IS NOT NULL"
                    else:
                        # NOT IN with empty list -> always true
                        return "(1=1)"
        # Default case: simple binary operator
        self._params.append(cond.value)
        return f"{cond.column} {cond.op.value} ?"


# Helper functions
def and_(*conditions) -> ConditionGroup:
    return ConditionGroup(conditions=list(conditions), logic="AND")

def or_(*conditions) -> ConditionGroup:
    return ConditionGroup(conditions=list(conditions), logic="OR")

def eq(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.EQ, value=val)

def ne(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.NE, value=val)

def lt(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.LT, value=val)

def gt(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.GT, value=val)

def in_(col: str, vals: List[Any]) -> Condition:
    return Condition(column=col, op=Op.IN, value=vals)

def not_in(col: str, vals: List[Any]) -> Condition:
    return Condition(column=col, op=Op.NOT_IN, value=vals)

def is_null(col: str) -> Condition:
    return Condition(column=col, op=Op.IS_NULL)

def between(col: str, low: Any, high: Any) -> Condition:
    return Condition(column=col, op=Op.BETWEEN, value=[low, high])


# Failing test (demonstrates original bug; should pass with the fixed builder)
def test_in_not_in_with_nulls_inside_or():
    # IN with NULL inside an OR group
    qb1 = QueryBuilder("users").select("id").where(
        or_(
            in_("status", [1, None]),
            eq("type", 2)
        )
    )
    sql1, params1 = qb1.build()
    expected_sql1 = "SELECT id FROM users WHERE (status IN (?) OR status IS NULL) OR type = ?"
    expected_params1 = [1, 2]
    assert sql1 == expected_sql1, f"SQL mismatch:\nEXPECTED: {expected_sql1}\nGOT:      {sql1}"
    assert params1 == expected_params1, f"Params mismatch: expected {expected_params1}, got {params1}"

    # NOT IN with NULL inside an OR group
    qb2 = QueryBuilder("users").select("id").where(
        or_(
            not_in("status", [1, None]),
            eq("type", 2)
        )
    )
    sql2, params2 = qb2.build()
    expected_sql2 = "SELECT id FROM users WHERE (status NOT IN (?) AND status IS NOT NULL) OR type = ?"
    expected_params2 = [1, 2]
    assert sql2 == expected_sql2, f"SQL mismatch:\nEXPECTED: {expected_sql2}\nGOT:      {sql2}"
    assert params2 == expected_params2, f"Params mismatch: expected {expected_params2}, got {params2}"

    # Only-NULL IN should become IS NULL
    qb3 = QueryBuilder("t").select("id").where(in_("col", [None]))
    sql3, params3 = qb3.build()
    assert sql3 == "SELECT id FROM t WHERE col IS NULL"
    assert params3 == []

    # Only-NULL NOT IN should become IS NOT NULL
    qb4 = QueryBuilder("t").select("id").where(not_in("col", [None]))
    sql4, params4 = qb4.build()
    assert sql4 == "SELECT id FROM t WHERE col IS NOT NULL"
    assert params4 == []

    print("All NULL-IN/NOT-IN tests passed.")


if __name__ == "__main__":
    # Run the test function when executed as a script
    test_in_not_in_with_nulls_inside_or()
```
